<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { api } from '../api';
import type { Classroom, Member } from '../api/types';
import AsyncState from '../components/AsyncState.vue';
import StudentImportDialog from '../components/StudentImportDialog.vue';
const rows = ref<Classroom[]>([]); const members = ref<Member[]>([]); const selected = ref(''); const loading = ref(true); const memberLoading = ref(false); const error = ref(''); const memberError = ref('');
const importing = ref(false); const memberPage = ref(1); const memberTotal = ref(0);
const creating = ref(false); const adding = ref(false); const saving = ref(false); const className = ref(''); const studentId = ref('');
let memberRequest = 0;
async function loadMembers() { const token = ++memberRequest; const classId = selected.value; memberLoading.value = true; memberError.value = ''; try { const response = await api.members(classId, memberPage.value); if (token === memberRequest) { members.value = response.items; memberTotal.value = response.total; } } catch (e) { if (token === memberRequest) memberError.value = (e as Error).message; } finally { if (token === memberRequest) memberLoading.value = false; } }
async function load() { loading.value = true; error.value = ''; try { rows.value = (await api.classes()).items; if (rows.value.length) { if (!rows.value.some(c => c.id === selected.value)) selected.value = rows.value[0]!.id; await loadMembers(); } } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
async function create() { if (!className.value.trim()) return; saving.value = true; try { const c = await api.createClass(className.value.trim()); selected.value = c.id; creating.value = false; className.value = ''; await load(); ElMessage.success('班级已创建'); } catch (e) { ElMessage.error((e as Error).message); } finally { saving.value = false; } }
async function add() { if (!studentId.value.trim() || !selected.value) return; saving.value = true; try { await api.addMember(selected.value, studentId.value.trim()); adding.value = false; studentId.value = ''; await load(); ElMessage.success('学生已加入班级'); } catch (e) { ElMessage.error((e as Error).message); } finally { saving.value = false; } }
onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><div><h1>教学班级</h1></div><el-button type="primary" @click="creating = true">＋ 创建班级</el-button></div><AsyncState :loading="loading" :error="error" :empty="!rows.length" empty-text="还没有教学班级，可以创建一个新班级。" @retry="load"><div class="class-grid"><button v-for="c in rows" :key="c.id" class="class-card panel" :class="{ selected: c.id === selected }" @click="selected = c.id; memberPage = 1; loadMembers()"><span class="class-icon">班</span><strong>{{ c.name }}</strong><span>{{ c.memberCount }} 位学生</span></button></div><div class="section-bar"><h2>学生名单 <span>{{ memberTotal }} 人</span></h2><div class="action-group"><el-button @click="adding = true">加入已有学生</el-button><el-button type="primary" @click="importing = true">导入学生</el-button></div></div><AsyncState :loading="memberLoading" :error="memberError" :empty="!members.length" empty-text="班级暂未添加学生。" @retry="loadMembers"><div class="panel table-panel"><el-table :data="members"><el-table-column prop="studentNumber" label="学号" /><el-table-column prop="name" label="姓名" /><el-table-column prop="id" label="用户编号" /></el-table><el-pagination v-if="memberTotal > 100" v-model:current-page="memberPage" :page-size="100" :total="memberTotal" layout="prev, pager, next" @current-change="loadMembers"/></div></AsyncState></AsyncState><el-dialog v-model="creating" title="创建教学班级" width="450px"><el-form label-position="top" @submit.prevent="create"><el-form-item label="班级名称"><el-input v-model="className" maxlength="100" placeholder="例如：计算机 2026 级 1 班" /></el-form-item></el-form><template #footer><el-button @click="creating = false">取消</el-button><el-button type="primary" :disabled="!className.trim()" :loading="saving" @click="create">创建班级</el-button></template></el-dialog><el-dialog v-model="adding" title="加入已有学生" width="450px"><p class="muted">学生须已拥有系统账号。请输入管理员提供的学生用户编号。</p><el-form label-position="top" @submit.prevent="add"><el-form-item label="学生用户编号"><el-input v-model="studentId" placeholder="输入学生用户编号" /></el-form-item></el-form><template #footer><el-button @click="adding = false">取消</el-button><el-button type="primary" :disabled="!studentId.trim()" :loading="saving" @click="add">加入班级</el-button></template></el-dialog><StudentImportDialog v-if="importing && selected" :key="selected" :class-id="selected" :class-name="rows.find(c=>c.id===selected)?.name || ''" @close="importing=false" @done="load"/></div></template>
